export function solve(capacity, operations) {
  const q = [];
  const out = [];

  for (const [op, v] of operations) {
    if (op === "push") {
      if (q.length >= capacity) {
        out.push(false);
      } else {
        q.push(v);
        out.push(true);
      }
    } else {
      out.push(q.length ? q.shift() : null);
    }
  }

  return out;
}
```

The corrected guard, `q.length >= capacity`, restores the invariant that queue length never exceeds capacity: full queues reject pushes without mutation, and pops preserve FIFO order. At capacity zero, every push is rejected. The synchronous API is unchanged; no dependencies or test edits are needed.

